<template>
  <section class="instance-workspace">
    <div class="instance-hero">
      <div class="instance-hero-icon"><img :src="icon || fallback" :alt="instance.name" /></div>
      <div class="instance-hero-copy"><div class="eyebrow">INSTANCE WORKSPACE</div><h1>{{ instance.name }}</h1><p>{{ details?.minecraftVersion || instance.runtime?.minecraft || 'Minecraft' }} · {{ instance.type || '客户端' }}<span v-if="details?.root"> · {{ details.root }}</span></p></div>
      <div class="instance-hero-actions"><q-btn flat icon="folder_open" label="打开目录" :disable="busy" @click="emit('open-folder')" /><q-btn flat icon="tune" label="实例设置" :disable="busy" @click="emit('settings')" /><q-btn color="positive" icon="play_arrow" label="启动" :disable="busy || instance.running" @click="emit('launch')" /></div>
    </div>
    <div class="workspace-toolbar"><q-btn-toggle v-model="section" flat toggle-color="primary" :options="[{label:'概览',value:'overview'},{label:'资源',value:'resources'},{label:'组件',value:'components'},{label:'控制台',value:'console'}]" /><q-space/><q-btn flat icon="more_horiz" label="更多操作" @click="moreShown=true" /></div>
    <template v-if="section==='overview'"><XmclHomeGrid :instance="instance.id" :execute="execute" @navigate="goResource" @extras="section='resources'" /><div class="overview-grid"><q-card class="workspace-card"><q-card-section><div class="card-heading"><span>实例信息</span><q-icon name="info" /></div><div class="info-grid"><div><small>实例目录</small><code>{{ details?.root || '读取中…' }}</code></div><div><small>游戏目录</small><code>{{ details?.gameRoot || '读取中…' }}</code></div><div><small>模组目录</small><code>{{ details?.modsRoot || '读取中…' }}</code></div><div><small>运行时间</small><code>{{ instance.playTimeSeconds || 0 }} 秒</code></div></div></q-card-section></q-card><q-card class="workspace-card"><q-card-section><div class="card-heading"><span>备注</span><q-icon name="edit_note" /></div><q-input v-model="localNotes" dark outlined autogrow placeholder="给这个实例留一条备注" /><q-btn class="q-mt-sm" color="primary" label="保存备注" :disable="busy" @click="emit('save-notes', localNotes)" /></q-card-section></q-card></div></template>
    <template v-else-if="section==='resources'"><div class="resource-switcher"><q-tabs v-model="resourceKind" align="left" outside-arrows><q-tab v-for="item in resourceKinds" :key="item.value" :name="item.value" :label="item.label" /></q-tabs></div><XmclResourceWorkspace :instance="instance.id" :kind="resourceKind" :minecraft-version="details?.minecraftVersion" :busy="busy" :execute="execute" /><ResourceUpdatesPanel :instance="instance.id" :kind="resourceKind" :busy="busy" :execute="execute" /><InstanceExtras :instance="instance.id" :busy="busy" :execute="execute" @changed="emit('refresh')" /></template>
    <template v-else-if="section==='components'"><q-card class="workspace-card"><q-card-section><div class="card-heading"><span>版本组件</span><q-btn flat icon="refresh" :disable="busy" @click="emit('refresh')" /></div><q-banner v-if="componentError" class="bg-red-9 q-mb-sm">{{ componentError }}</q-banner><q-list bordered separator><q-item v-for="component in components" :key="component.id"><q-item-section><q-item-label>{{ component.name || component.id }} <span class="text-grey-5">{{ component.version }}</span></q-item-label><q-item-label caption>{{ component.id }} · {{ component.enabled ? '已启用' : '已禁用' }}</q-item-label><q-item-label v-for="problem in component.problems || []" :key="problem.description" class="text-orange">{{ problem.description }}</q-item-label></q-item-section><q-item-section side><q-btn v-if="component.canChangeVersion" flat label="更改版本" :disable="busy" @click="editComponent(component)" /><q-btn v-if="component.canDisable" flat :label="component.enabled ? '禁用' : '启用'" :disable="busy" @click="emit('component-enabled', component, !component.enabled)" /></q-item-section></q-item><q-item v-if="!components.length"><q-item-section class="text-grey-5">没有可显示的组件。</q-item-section></q-item></q-list></q-card-section></q-card></template>
    <template v-else><q-card class="workspace-card console-card"><q-card-section><div class="console-toolbar"><div><strong>实时控制台</strong><small>{{ consoleState }}</small></div><q-space/><q-btn flat label="连接" icon="link" :disable="busy" @click="emit('connect-console')" /><q-btn flat label="清空" icon="clear_all" @click="emit('clear-console')" /><q-checkbox v-model="follow" dark label="自动滚动" /></div><pre class="console">{{ consoleLines.join('\n') || '启动实例后，日志会实时显示在这里。' }}</pre><q-separator class="q-my-md"/><div class="console-toolbar"><strong>历史日志</strong><q-space/><q-select class="log-select" dark outlined dense v-model="selectedLog" :options="logFiles.map((f:any)=>({label:f.name,value:f.path}))" emit-value map-options label="日志文件" /><q-btn flat label="读取" :disable="busy || !selectedLog" @click="emit('read-log', selectedLog)" /></div><pre v-if="fileLog" class="console history">{{ fileLog }}</pre></q-card-section></q-card></template>
    <q-dialog v-model="moreShown"><q-card class="more-card text-white"><q-card-section><div class="text-h6">实例操作</div></q-card-section><q-list><q-item v-for="item in actions" :key="item.op" clickable v-close-popup :disable="busy" @click="action(item)"><q-item-section avatar><q-icon :name="item.icon" /></q-item-section><q-item-section>{{ item.label }}</q-item-section></q-item><q-item clickable v-close-popup :disable="busy" @click="emit('change-icon')"><q-item-section avatar><q-icon name="image" /></q-item-section><q-item-section>更换图标</q-item-section></q-item><q-item clickable v-close-popup :disable="busy" @click="emit('delete')"><q-item-section avatar><q-icon name="delete" color="negative" /></q-item-section><q-item-section class="text-negative">删除实例</q-item-section></q-item></q-list></q-card></q-dialog>
    <q-dialog v-model="versionShown"><q-card class="more-card text-white"><q-card-section class="text-h6">更改 {{ editing?.name || editing?.id }} 版本</q-card-section><q-card-section><q-input v-model="version" dark outlined label="组件版本" autofocus /></q-card-section><q-card-actions align="right"><q-btn flat label="取消" @click="versionShown=false" /><q-btn color="primary" label="保存" :disable="!version.trim()" @click="saveVersion" /></q-card-actions></q-card></q-dialog>
  </section>
</template>
<script setup lang="ts">
import { ref, watch } from 'vue';
import XmclHomeGrid from './XmclHomeGrid.vue';
import XmclResourceWorkspace from './XmclResourceWorkspace.vue';
import ResourceUpdatesPanel from '../components/ResourceUpdatesPanel.vue';
import InstanceExtras from '../components/InstanceExtras.vue';
import fallback from './assets/minecraft.webp';
const props=defineProps<{instance:any;details:any;icon?:string;components:any[];componentError?:string;notes:string;busy:boolean;execute:(op:string,p?:Record<string,unknown>)=>Promise<any>;consoleLines:string[];consoleState:string;logFiles:any[];fileLog:string}>();
const emit=defineEmits<{launch:[];'open-folder':[];settings:[];delete:[];'change-icon':[];'save-notes':[notes:string];refresh:[];'connect-console':[];'clear-console':[];'read-log':[file:string];'component-enabled':[component:any,enabled:boolean];'component-version':[component:any,version:string];action:[op:string]}>();
const section=ref('overview'), resourceKind=ref('mods'), localNotes=ref(props.notes), follow=ref(true), selectedLog=ref(''), moreShown=ref(false), versionShown=ref(false), editing=ref<any>(null), version=ref('');
const resourceKinds=[{label:'模组',value:'mods'},{label:'资源包',value:'resourcepacks'},{label:'光影',value:'shaderpacks'},{label:'数据包',value:'datapacks'},{label:'投影',value:'schematics'}]; const actions=[{op:'rename',label:'重命名',icon:'edit'},{op:'copy',label:'复制实例',icon:'content_copy'},{op:'group',label:'修改分组',icon:'folder'},{op:'update',label:'更新组件',icon:'system_update'},{op:'verify',label:'校验文件',icon:'verified'},{op:'stop',label:'停止运行',icon:'stop'}];
watch(()=>props.notes,v=>localNotes.value=v);
function goResource(kind:string){if(kind==='save'){section.value='overview';return;}resourceKind.value=kind;section.value='resources';}
function action(item:any){emit('action', item.op);}
function editComponent(component:any){editing.value=component;version.value=component.version || '';versionShown.value=true;}
function saveVersion(){if(editing.value && version.value.trim())emit('component-version',editing.value,version.value.trim());versionShown.value=false;}
</script>
<style scoped>
