word;background:#090d15;padding:16px;border-radius:10px;color:#dbeafe;font:12px/1.55 ui-monospace,SFMono-Regular,Consolas,monospace}.console.history{height:220px}.log-select{min-width:0;width:min(220px,35vw)}.more-card{min-width:330px;max-width:92vw;background:#20202a!important;border-radius:16px}.more-card :deep(.q-item){min-height:46px}.more-card :deep(.q-btn){text-transform:none}@media(max-width:900px){.instance-hero{display:block}.instance-hero-actions{margin-top:16px;flex-wrap:wrap}.overview-grid{grid-template-columns:1fr;padding:0 8px}.instance-workspace{padding:8px 10px 36px}.info-grid{grid-template-columns:1fr}.workspace-toolbar{overflow:auto}.log-select{min-width:140px;width:140px}}
</style>
